window.RMSResponseExamples={"version":"2.11","promise":"Examples illustrate the expected type, length, and specificity. They are hypothetical models, not verified student submissions or research findings, and never populate your field automatically.","field_count":113,"fields":{"interest1":{"stage":1,"label":"Three science or research areas I enjoy","type":"textarea","expected_shape":"exactly 3 short topic areas","typical_length":"about 3–15 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Science, biology, and other things.","good_working_response":"Plant physiology; human memory and learning; freshwater ecosystem health.","detailed_response":"","why_it_works":"List three distinct areas that interest you. You may include a curiosity within each; none needs to be a research question yet."},"problem1":{"stage":1,"label":"A problem or pattern I have noticed","type":"textarea","expected_shape":"1–2 focused sentences","typical_length":"about 10–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Students forget things.","good_working_response":"Hypothetical classroom pattern: Some students recall vocabulary on quiz day but struggle to retrieve it a week later.","detailed_response":"","why_it_works":"Identify an observable pattern and the specific uncertainty it raises. Present an illustrative observation as hypothetical."},"claim1":{"stage":1,"label":"A claim I would like to investigate","type":"textarea","expected_shape":"one claim that could be investigated","typical_length":"about 5–35 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Music always helps everybody learn.","good_working_response":"Using music while studying improves memory.","detailed_response":"","why_it_works":"Write the claim as someone might say it, then keep an open mind about whether the evidence will support it."},"access1":{"stage":1,"label":"Resources, settings, people, organisms, tools, or datasets I can realistically access","type":"textarea","expected_shape":"4–8 concrete resources, settings, tools, organisms, people, or datasets","typical_length":"about 10–50 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Google and some articles.","good_working_response":"School greenhouse plants, a classroom thermometer, peer-reviewed databases, and publicly available weather data.","detailed_response":"","why_it_works":"List what you can access safely and with appropriate permission."},"ideaA":{"stage":1,"label":"Possible direction A","type":"textarea","expected_shape":"one possible research direction","typical_length":"about 10–40 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Do an experiment with soil.","good_working_response":"Compare water loss from identical soil containers placed under two light conditions.","detailed_response":"","why_it_works":"Write a short direction that connects an interest to a possible kind of evidence."},"ideaB":{"stage":1,"label":"Possible direction B","type":"textarea","expected_shape":"one possible research direction","typical_length":"about 10–40 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Read about studying.","good_working_response":"Review published studies comparing retrieval practice and rereading in science learning.","detailed_response":"","why_it_works":"Generate another route, preferably using a different question, context, or type of evidence."},"ideaC":{"stage":1,"label":"Possible direction C","type":"textarea","expected_shape":"one possible research direction","typical_length":"about 10–40 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Research shade.","good_working_response":"Observe whether shaded and unshaded school surfaces differ in afternoon temperature.","detailed_response":"","why_it_works":"Write another feasible option before you decide which project to pursue."},"broadTopic":{"stage":2,"label":"Broad area","type":"text","expected_shape":"a short topic phrase","typical_length":"about 2–6 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Science.","good_working_response":"Plant stress.","detailed_response":"","why_it_works":"Choose one broad area. The next field will narrow it to a subtopic."},"subtopic":{"stage":2,"label":"Specific subtopic","type":"text","expected_shape":"a narrower topic phrase","typical_length":"about 3–12 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Plants.","good_working_response":"Early seedling responses to salinity.","detailed_response":"","why_it_works":"Name the specific process, relationship, population, mechanism, or context you want to focus on."},"phenomenon":{"stage":2,"label":"Phenomenon, relationship, experience, or problem","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 10–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Salt affects plants.","good_working_response":"Possible pattern to investigate: Seedling growth may differ across salt concentrations.","detailed_response":"","why_it_works":"Describe a possible observation or relationship without presenting an unmeasured pattern as a finding."},"contextPop":{"stage":2,"label":"Population, system, organism, setting, or context","type":"textarea","expected_shape":"a defined population or setting, as a phrase or short sentence","typical_length":"about 5–35 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Students.","good_working_response":"Bean seedlings grown in classroom trays during a 7-day period.","detailed_response":"","why_it_works":"Name the population, organism, system, setting, and useful boundaries."},"scope":{"stage":2,"label":"What part of the issue I can realistically study","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 10–55 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Everything about plant stress.","good_working_response":"I would measure early seedling growth over seven days, leaving long-term plant survival outside the project's scope.","detailed_response":"","why_it_works":"State what you will focus on and what you will leave outside the project."},"timeLimit":{"stage":2,"label":"Time available","type":"text","expected_shape":"one short statement of the actual time available","typical_length":"about 5–20 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"As long as I need.","good_working_response":"Six weeks total, with about eight class periods available for data collection.","detailed_response":"","why_it_works":"State the calendar or number of class periods/weeks you truly have."},"resources":{"stage":2,"label":"Equipment/data/source access","type":"textarea","expected_shape":"a short list of required resources, with access status where relevant","typical_length":"about 10–65 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Some equipment.","good_working_response":"Digital balance; labelled containers; salinity solutions prepared with supervision; spreadsheet software; teacher approval for laboratory space still needed.","detailed_response":"","why_it_works":"Distinguish resources already available from materials or permissions still needed. A materials list does not establish an adequate sample size."},"safety":{"stage":2,"label":"Safety or ethics concerns I can already see","type":"textarea","expected_shape":"1–3 focused sentences identifying risks and possible safeguards","typical_length":"about 15–85 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"It should be safe.","good_working_response":"Assigning caffeine intake to students could pose health and consent concerns, especially where a teacher recruits participants. I would avoid this intervention and consider a literature-based question instead.","detailed_response":"","why_it_works":"Identify possible harm, pressure or privacy concerns early. Human participation may require permission, ethical review and genuinely voluntary consent."},"topicChoice":{"stage":2,"label":"Working research topic","type":"textarea","expected_shape":"a short phrase or one sentence","typical_length":"about 3–25 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Something with plants.","good_working_response":"Early seedling growth under different salinity conditions.","detailed_response":"","why_it_works":"State the chosen topic as a specific phrase and briefly keep its boundaries in mind."},"concepts":{"stage":3,"label":"Core concepts","type":"textarea","expected_shape":"2–4 central search concepts","typical_length":"about 4–25 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Learning, things, scores.","good_working_response":"retrieval practice; biology learning; delayed recall","detailed_response":"","why_it_works":"Select a few central concepts that carry the research question's meaning; separate them so each can be searched with suitable terms."},"synonyms":{"stage":3,"label":"Synonyms and related terms","type":"textarea","expected_shape":"2–4 concepts with synonyms or clearly identified related search terms","typical_length":"about 15–65 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Memory means memory stuff.","good_working_response":"retrieval practice: practice testing, test-enhanced learning; delayed recall: retention after a delay; related search term: delayed test","detailed_response":"","why_it_works":"Gather alternatives for each concept while distinguishing true synonyms from related terms that may refer to different measures."},"prelimSearch":{"stage":3,"label":"Two or three preliminary search strings","type":"textarea","expected_shape":"2–3 preliminary search strings with a short note about what each revealed","typical_length":"about 30–100 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I looked up retrieval practice on the internet.","good_working_response":"Illustrative search plan, not completed searches. ERIC: (\"retrieval practice\" OR \"practice testing\") AND biology. Scopus: \"retrieval practice\" AND \"delayed recall\". Google Scholar: \"practice testing\" science classroom. For each search, record the date, actual sources found and any useful terms or methods.","detailed_response":"","why_it_works":"Use these strings as possible starting points. Report what each search actually revealed after running it; do not invent search results."},"known":{"stage":3,"label":"What appears reasonably well established","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Research proves testing works.","good_working_response":"Possible claim to verify against identified studies: Retrieval practice may improve delayed recall under some learning conditions. Record the supporting sources, populations and measurement conditions before calling this established.","detailed_response":"","why_it_works":"Build a qualified synthesis from studies you have actually read, with references and attention to where their findings apply."},"methodsSeen":{"stage":3,"label":"Methods or measurements used in existing studies","type":"textarea","expected_shape":"3–6 specific items, short phrases, or bullets","typical_length":"about 20–80 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"They did tests.","good_working_response":"Illustrative extraction categories, not findings from a completed search: delayed-recall tests; comparisons of assigned study conditions; time between learning and measurement. Replace these with methods documented in the sources you examined.","detailed_response":"","why_it_works":"Identify methods in specific papers before describing them as common or recurring in the literature."},"uncertain":{"stage":3,"label":"What appears uncertain, inconsistent, underexplored, or context-dependent","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"More research is needed.","good_working_response":"Possible uncertainty to check: If the studies I find assess recall at different intervals, do reported effects differ between 24 and 48 hours? I would compare their methods and results before claiming an unresolved gap.","detailed_response":"","why_it_works":"Describe a question to investigate in the literature. An apparent difference between studies is not itself proof of a research gap."},"questionShift":{"stage":3,"label":"How my possible question changed after reading","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I made the question better.","good_working_response":"I revised my question from “Does sleep improve grades?” to “What is the association between self-reported weekday sleep duration and biology quiz score?” because I would observe sleep rather than assign it.","detailed_response":"","why_it_works":"Write the earlier idea and the improved direction, then explain what caused the change."},"rq1":{"stage":4,"label":"Draft question 1","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Does studying help?","good_working_response":"What is the association between reported weekly study time and delayed biology recall score among students in this class?","detailed_response":"","why_it_works":"Write one answerable question using the best current wording."},"rq2":{"stage":4,"label":"Draft question 2","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Is one study method better?","good_working_response":"How does delayed recall differ between two assigned study procedures under the same content conditions?","detailed_response":"","why_it_works":"Compare this question with the first. Assigning study procedures changes the design and may require ethical approval and safeguards for student participation."},"rq3":{"stage":4,"label":"Draft question 3","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 10–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"What do students think about things?","good_working_response":"How do students describe the study strategies they use after receiving assessment feedback?","detailed_response":"","why_it_works":"Write another defensible question and compare it with the first two."},"questionType":{"stage":4,"label":"Question family","type":"select","expected_shape":"one selection","typical_length":"Choose the option that matches your project. Use the nearby explanation field to justify it when one is provided.","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I chose a category because it sounds more scientific.","good_working_response":"For a question about whether sleep duration is associated with scores, select “Correlational / observational”.","detailed_response":"","why_it_works":"Choose the available category that matches the proposed evidence and inference, then explain the choice in the nearby justification field."},"finalRQ":{"stage":4,"label":"Working research question","type":"textarea","expected_shape":"one complete sentence, sometimes two","typical_length":"about 15–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Does sleep affect students?","good_working_response":"What is the association between reported weekday sleep duration and biology quiz score among students in this class?","detailed_response":"","why_it_works":"Write one clear sentence that names the key phenomenon/variables and useful population/context. Use wording compatible with the design."},"rqJustification":{"stage":4,"label":"Why this question is feasible, ethical, and answerable with evidence","type":"textarea","expected_shape":"2–5 focused sentences","typical_length":"about 30–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"It is easy, and students can answer.","good_working_response":"Students could voluntarily report weekday sleep duration. Connecting survey responses to existing quiz records would require appropriate approval, consent and secure coded matching. The resulting observational study could examine association without establishing that sleep duration caused a score difference.","detailed_response":"A short questionnaire could collect students’ reports of weekday sleep duration if the school permits the proposed research and appropriate consent procedures are in place. Matching those reports to existing biology quiz scores would require authorized access to the records, secure coded identifiers and a plan for protecting student privacy. Students must be free to decline participation without consequences for grades or their relationship with the teacher. The study can be conducted without assigning sleep conditions, but self-reports and a single class may limit the interpretation. The research question therefore concerns the association between reported sleep duration and quiz performance, with no claim that one causes the other.","why_it_works":"Explain the evidence needed, realistic permissions and participant safeguards alongside the limits of the proposed inference."},"searchBlock1":{"stage":5,"label":"Concept block 1 and synonyms","type":"textarea","expected_shape":"2–5 useful terms for the first concept","typical_length":"about 4–30 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Studying.","good_working_response":"retrieval practice, practice testing, self-testing","detailed_response":"","why_it_works":"List the main term and several true synonyms or closely related research terms."},"searchBlock2":{"stage":5,"label":"Concept block 2 and synonyms","type":"textarea","expected_shape":"2–5 useful terms for the second concept","typical_length":"about 4–30 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Other words for learning.","good_working_response":"biology OR \"science learning\" OR \"science education\"","detailed_response":"","why_it_works":"Build the second concept block and check whether related terms broaden or narrow the meaning of the search."},"searchBlock3":{"stage":5,"label":"Population/context block if relevant","type":"textarea","expected_shape":"optional population or setting terms, when they improve precision","typical_length":"about 3–30 words when used","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Students.","good_working_response":"adolescent* OR \"high school\" OR \"secondary school\"","detailed_response":"","why_it_works":"Use this optional block for the population or context. Test whether adding it would wrongly exclude relevant studies."},"searchStrings":{"stage":5,"label":"Final Boolean search strings","type":"textarea","expected_shape":"2–4 complete Boolean search strings you could paste into a database","typical_length":"about 20–100 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I searched for biology tests.","good_working_response":"(\"retrieval practice\" OR \"practice testing\") AND (biology OR \"science learning\"); (\"retrieval practice\" OR \"practice testing\") AND (adolescent* OR \"high school\") AND (retention OR \"delayed recall\")","detailed_response":"","why_it_works":"Preserve the concept-group logic and adapt quotation marks, truncation and field syntax to each database before recording the executed search."},"databases":{"stage":5,"label":"Databases/search tools I will use","type":"textarea","expected_shape":"2–5 databases/search systems plus a short reason for each","typical_length":"about 10–60 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Google and some articles.","good_working_response":"ERIC and Education Source for education research; Scopus for broader interdisciplinary coverage.","detailed_response":"","why_it_works":"Name each system and, when helpful, explain why it is appropriate for the topic."},"includeCriteria":{"stage":5,"label":"Inclusion criteria","type":"textarea","expected_shape":"3–6 clear inclusion rules, as a list or short statements","typical_length":"about 15–75 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Include good studies.","good_working_response":"Peer-reviewed empirical studies; participants learning science or biology; retrieval practice is defined; reports an outcome measured after learning.","detailed_response":"","why_it_works":"Set criteria that can be applied consistently before examining whether a study supports the expected result. Justify age or setting restrictions when used."},"excludeCriteria":{"stage":5,"label":"Exclusion criteria","type":"textarea","expected_shape":"3–6 clear exclusion rules, as a list or short statements","typical_length":"about 15–75 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Exclude studies I do not like.","good_working_response":"Exclude opinion pieces without original data for an empirical-only review; reports without a learning outcome; studies outside the predeclared education context.","detailed_response":"","why_it_works":"Specify exclusion rules that correspond to the review question and inclusion rules. Do not exclude studies because their findings disagree with an expectation."},"searchLog":{"stage":5,"label":"Search log or dates searched","type":"textarea","expected_shape":"one concise record per search; usually 2–6 rows/entries","typical_length":"about 30–150 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I found lots of useful articles.","good_working_response":"Illustrative blank search record, not an executed search. [Actual date] | ERIC | (\"retrieval practice\" OR \"practice testing\") AND biology | [filters used] | [actual hits] | [screened, if any] | [retained, if any] | [reason for next revision].","detailed_response":"","why_it_works":"Enter actual search dates, exact queries, filters and counts after performing each search. Do not turn a sample log into fabricated retrieval data."},"theme1":{"stage":7,"label":"Theme or convergence 1","type":"textarea","expected_shape":"1–2 source-grounded synthesis sentences","typical_length":"about 15–75 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"All the articles agree.","good_working_response":"Illustrative theme to verify: Retrieval-based practice may be linked with stronger delayed recall in the selected studies. Identify the papers, outcomes and exceptions before describing this as a convergent finding.","detailed_response":"","why_it_works":"Describe a documented pattern and show which specific sources support or complicate it."},"theme2":{"stage":7,"label":"Theme or convergence 2","type":"textarea","expected_shape":"1–2 source-grounded synthesis sentences","typical_length":"about 15–75 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Another study also agreed.","good_working_response":"Possible second theme to check: Feedback procedures may help explain differences in reported retrieval-practice outcomes. Compare the actual studies and their designs before drawing that conclusion.","detailed_response":"","why_it_works":"Develop a different pattern only when the included sources support it, identifying the relevant evidence."},"theme3":{"stage":7,"label":"Theme or convergence 3","type":"textarea","expected_shape":"1–2 source-grounded synthesis sentences","typical_length":"about 15–75 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The articles have limitations.","good_working_response":"If studies use different kinds of retention assessments, discuss how those measures affect the comparability of results. Name the papers and measures rather than assuming that all studies differ.","detailed_response":"","why_it_works":"Use the third theme for another substantiated relationship or limitation, not to fill a prescribed number of themes."},"tensions":{"stage":7,"label":"Contradictions, tensions, or boundary conditions","type":"textarea","expected_shape":"1–3 focused sentences grounded in compared sources","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The studies contradict one another.","good_working_response":"If two included studies report different retrieval-practice advantages, compare their retention intervals, feedback procedures and scoring before calling the findings contradictory. A difference in design may explain part of the contrast, but the evidence must establish that connection.","detailed_response":"","why_it_works":"Identify what differs and distinguish a plausible methodological explanation from one directly demonstrated."},"repeatedLimits":{"stage":7,"label":"Repeated methodological limitations","type":"textarea","expected_shape":"1–3 sentences identifying limitations in named studies","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The studies were not perfect.","good_working_response":"Check which retrieved studies used short retention intervals or convenience university samples. If these limitations recur, cite the relevant papers and explain how they constrain what can be concluded about secondary biology learners.","detailed_response":"","why_it_works":"Identify repeated limitations from the actual evidence base and explain their implications without treating all limitations as research gaps."},"gapType":{"stage":7,"label":"Best description","type":"select","expected_shape":"one selection","typical_length":"Choose the option that matches your project. Use the nearby explanation field to justify it when one is provided.","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Select “Documented literature gap” just because the local question is unfamiliar.","good_working_response":"If relevant research exists in other populations, choose “Extension to a new context/population” when that is the strongest supported rationale.","detailed_response":"","why_it_works":"Choose the narrowest defensible rationale. Evidence that a particular context differs does not establish that no earlier research exists."},"gapStatement":{"stage":7,"label":"Precise justification or gap statement","type":"textarea","expected_shape":"2–4 focused sentences","typical_length":"about 30–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"No one has ever researched this topic.","good_working_response":"If my recorded searches identify retrieval-practice studies but few in secondary biology classrooms, I could justify a local extension. I would name the searched databases, the relevant studies and the limits of the search before making that statement.","detailed_response":"","why_it_works":"Bound claims about a gap or extension to the search actually performed and avoid unsupported assertions about the entire literature."},"litToRQ":{"stage":7,"label":"How the literature leads to my research question","type":"textarea","expected_shape":"2–4 focused sentences","typical_length":"about 40–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Research proves this works, so I will test it.","good_working_response":"If the reviewed studies support benefits under particular conditions, their methods can help me choose a suitable delayed-recall outcome. I would then explain why examining that outcome in a secondary biology class is meaningful without claiming the classroom context has never been studied.","detailed_response":"","why_it_works":"Show how documented evidence, its limits and the proposed setting inform the question, with no claim broader than the search permits."},"litIntroPlan":{"stage":8,"label":"Opening, scope, and key definitions","type":"textarea","expected_shape":"2–4 connected planning sentences","typical_length":"about 30–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Introduce the topic and talk about some studies.","good_working_response":"I will define retrieval practice and explain how delayed recall is measured in the papers selected for review. The introduction will set the scope around science-learning contexts, while the following synthesis will develop only themes supported by the retrieved sources.","detailed_response":"","why_it_works":"Identify the relevant concepts and scope before developing evidence-based themes; a fixed sequence of paragraphs is unnecessary."},"litThemePlan":{"stage":8,"label":"Theme sequence and sources under each theme","type":"textarea","expected_shape":"3–6 specific items, short phrases, or bullets","typical_length":"about 20–80 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Summarize each article one by one.","good_working_response":"Possible theme sequence, pending evidence: delayed retention across outcomes; the role of feedback; differences in measures and their comparability. Under each theme, note the studies being compared and the point of agreement or disagreement.","detailed_response":"","why_it_works":"Organise the review through questions and relationships across actual sources. Revise the proposed themes when the evidence does not support them."},"litTensionPlan":{"stage":8,"label":"Where disagreement or limitations will appear","type":"textarea","expected_shape":"1–3 sentences about specific comparisons to make","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Mention that some studies are different.","good_working_response":"If selected studies report different effects, I will compare their feedback procedures, retention intervals and scoring methods before interpreting the difference. I will identify the papers involved and distinguish a possible explanation from a demonstrated one.","detailed_response":"","why_it_works":"Plan where source-specific disagreement belongs and which methodological differences warrant examination."},"litEndPlan":{"stage":8,"label":"How the review will lead to the study purpose/question","type":"textarea","expected_shape":"1–3 sentences explaining the bridge to the question","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"End by saying more research is needed.","good_working_response":"The review will close by explaining which reported patterns are supported, which contexts or measures limit their interpretation, and what follows for my proposed question. A local extension will be justified by the actual sources rather than an assumed absence of research.","detailed_response":"","why_it_works":"Connect the review to the study purpose through the evidence you have, without manufacturing a global research gap."},"litDraft":{"stage":8,"label":"Literature review draft","type":"textarea","expected_shape":"2–5 connected paragraphs","typical_length":"250–600 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Several papers say learning is important.","good_working_response":"Illustrative opening only. Retrieval practice involves recalling previously studied material without consulting the source. A literature review should then compare documented findings from named studies and explain how their methods and contexts bear on the proposed question.","detailed_response":"Retrieval practice describes activities in which learners try to bring previously studied material to mind, such as answering questions without consulting notes. Dunlosky and colleagues (2013) reviewed practice testing alongside other learning techniques, examining their usefulness across different learning conditions, learners, materials and outcome tasks. Their review provides a starting point for defining the approach. Its broad scope, however, cannot establish what happened in the particular secondary biology studies that a student might later select.\n\nFor the papers retrieved in my own search, I would compare [insert study A] and [insert study B] in terms of the learning activities they assigned or observed, the interval before measuring retention, and the forms of knowledge the assessments captured. If their results point in similar directions, I would describe that convergence using the reported findings and citations. Where the outcomes differ, I would examine whether differences in student groups, feedback procedures, or measures offer plausible explanations. I would not treat a contrast between two research designs as evidence that one design feature caused their different results without stronger support.\n\nThe relationship between that evidence and a secondary biology project would then need to be explained with care. A local classroom investigation may be valuable for its curricular context even if studies of retrieval practice already exist elsewhere. I would identify the specific studies supporting any statement about a recurring pattern, an underexplored population, or a methodological limitation. The final literature review would replace these planning notes and bracketed references with a connected synthesis of actual retrieved studies, accurate citations, and a research question warranted by what those sources show.","why_it_works":"Use the longer illustration to see how connected paragraphs can develop an argument. Replace its planning language and bracketed sources with your own verified synthesis and complete references."},"designType":{"stage":9,"label":"Primary design","type":"select","expected_shape":"one selection","typical_length":"Choose the option that matches your project. Use the nearby explanation field to justify it when one is provided.","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Experimental, because I have two existing groups.","good_working_response":"Correlational / observational","detailed_response":"","why_it_works":"Select the exact design option that matches how the proposed evidence will be obtained. Measuring existing sleep patterns and scores does not constitute assigning a treatment."},"designWhy":{"stage":9,"label":"Why this design can answer my question","type":"textarea","expected_shape":"2–4 focused sentences explaining the design","typical_length":"about 25–105 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I chose it because it is easy.","good_working_response":"Students would report their usual sleep duration without being assigned sleep conditions. An observational correlational design could examine whether reported sleep and biology quiz scores vary together. Other factors may influence both, so the study could not establish a causal effect of sleep.","detailed_response":"","why_it_works":"Connect the kind of evidence obtained to the inference the research question permits, and acknowledge important alternative explanations."},"comparisonStructure":{"stage":9,"label":"What is compared or observed, if anything","type":"textarea","expected_shape":"a specific description of units, conditions or observations","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I will compare the groups.","good_working_response":"Illustrative experiment with three salinity levels (0, 50 and 100 mM NaCl). Eighteen independently assigned dishes would provide six dishes per level, with five seeds observed within each dish. One dish-level mean would enter the primary treatment comparison.","detailed_response":"","why_it_works":"Identify the comparison and specify which units are assigned independently. Measurements nested within a dish are not separate treatment replicates."},"claimBoundary":{"stage":9,"label":"What this design will and will not allow me to claim","type":"textarea","expected_shape":"1–3 sentences distinguishing supported and unsupported claims","typical_length":"about 20–85 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I can prove whether it works.","good_working_response":"An observational study in one class could estimate the association between reported phone use and quiz scores among participating students. It could not, by itself, establish that phone use causes lower scores or justify generalizing to all secondary students.","detailed_response":"","why_it_works":"State what the design and sample permit you to conclude, and identify at least one important claim they cannot support."},"hypothesisNeeded":{"stage":10,"label":"Does this study need a formal hypothesis?","type":"select","expected_shape":"one selection","typical_length":"Choose the option that matches your project. Use the nearby explanation field to justify it when one is provided.","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Yes, because every research project needs one.","good_working_response":"No","detailed_response":"","why_it_works":"For a descriptive survey of species frequencies, select “No” if a prespecified hypothesis would not serve the research question. Explain the choice in the related field."},"researchHyp":{"stage":10,"label":"Research or directional hypothesis if appropriate","type":"textarea","expected_shape":"one prespecified prediction, usually a sentence","typical_length":"about 10–50 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Salt will affect the plants.","good_working_response":"Dishes assigned higher NaCl concentrations will have a lower mean shoot length per planted seed on Day 7.","detailed_response":"","why_it_works":"Identify the predicted direction and the precise outcome before seeing the data. The prediction should have a reason grounded in prior evidence or a plausible mechanism."},"nullHyp":{"stage":10,"label":"Null hypothesis if an inferential test is planned","type":"textarea","expected_shape":"one statistical null statement matched to the planned comparison","typical_length":"about 15–70 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Nothing will happen.","good_working_response":"The population mean dish-level shoot length per planted seed on Day 7 is equal under 0 mM and 100 mM NaCl; the mean difference between these conditions is zero.","detailed_response":"","why_it_works":"Express the null in terms of the population parameter and contrast that the selected analysis actually tests."},"hypReason":{"stage":10,"label":"Evidence or theory supporting the prediction","type":"textarea","expected_shape":"2–4 sentences explaining the proposed prediction","typical_length":"about 25–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I know salt is bad for plants.","good_working_response":"Added salt may alter the water available to developing seedlings. I would consult relevant plant physiology studies to judge whether this supports a directional prediction for seven-day shoot length. I would record the prediction before measurements begin, rather than infer it from the results.","detailed_response":"","why_it_works":"Identify a plausible mechanism and the evidence still needed to justify the direction. Keep the timing of the hypothesis clear."},"predictorIV":{"stage":10,"label":"Manipulated IV or measured predictor/exposure","type":"textarea","expected_shape":"a named predictor or treatment with its status","typical_length":"about 8–55 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The independent variable is whatever changes.","good_working_response":"For the proposed dish experiment, the manipulated factor is assigned NaCl concentration, at 0, 50 or 100 mM. In a separate observational sleep study, reported hours of sleep would be a measured predictor rather than a treatment.","detailed_response":"","why_it_works":"Use assigned-treatment language for experiments and measured-exposure language for observational research."},"outcomeDV":{"stage":10,"label":"Outcome/dependent variable","type":"textarea","expected_shape":"a precise outcome with measurement time and units","typical_length":"about 15–65 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Plant growth.","good_working_response":"Mean shoot length per planted seed in each dish on Day 7, in centimetres. Seeds that have not germinated are recorded as 0 cm under this prespecified combined germination-and-growth outcome.","detailed_response":"","why_it_works":"Define a measurable outcome and identify the unit of analysis. A zero for an ungerminated seed must be justified as part of the chosen outcome definition."},"operationalDefs":{"stage":10,"label":"Operational definitions and units","type":"textarea","expected_shape":"2–5 specific sentences defining key variables and units","typical_length":"about 35–135 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"We measure growth and compare conditions.","good_working_response":"NaCl treatment is the assigned concentration of 0, 50 or 100 mM. On Day 7, measure each seed's shoot length from the substrate surface to the shoot tip in centimetres. Record 0 cm for an ungerminated seed and calculate the mean across all five planted seeds in each dish.","detailed_response":"The manipulated treatment is the nominal concentration of the NaCl solution assigned to a dish, recorded as 0, 50 or 100 mmol/L. Five seeds are planted in each independently assigned dish. Seven days after setup, shoot length is measured from the substrate surface to the shoot tip using the same ruler and measurement rule. Seeds without visible shoot growth are recorded as 0 cm, so the prespecified outcome is mean shoot length per planted seed, reflecting both germination and subsequent growth. Each seed retains its own identifier within its dish, and the five measurements contribute one dish-level mean for the primary treatment comparison. Germination status is retained separately to help interpret any difference in the combined outcome.","why_it_works":"Specify treatment, timing, measurement boundaries, units and aggregation. The analysis must respect the dish-level treatment allocation."},"controlCondition":{"stage":10,"label":"Control/comparison group or condition, if applicable","type":"textarea","expected_shape":"a short explanation of the reference condition","typical_length":"about 10–55 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The normal group.","good_working_response":"Dishes assigned 0 mM NaCl, with no salt added to their solution, provide the reference for comparing the 50 mM and 100 mM treatment dishes.","detailed_response":"","why_it_works":"Identify the reference and explain what differs from the other conditions. Keep a control group distinct from procedures held constant."},"controlledConditions":{"stage":10,"label":"Controlled conditions / standardized procedures","type":"textarea","expected_shape":"4–8 conditions or procedures intended to stay consistent","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Keep everything the same.","good_working_response":"Same radish-seed batch; substrate type and amount; solution volume; dish size; temperature range; light schedule; Day 7 measurement timing; and ruler-based scoring method.","detailed_response":"","why_it_works":"List feasible controls that could affect the outcome. Randomise or document remaining sources of variation rather than claiming complete control."},"confounders":{"stage":10,"label":"Potential confounders or alternative explanations","type":"textarea","expected_shape":"2–5 plausible alternative factors, with how they may matter","typical_length":"about 30–140 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Age, weather and other things.","good_working_response":"Previous biology achievement may relate to both study time and quiz performance, creating an alternative explanation for their association. Attendance could also influence opportunities to study and the material students have encountered. Measure these only where authorized and relevant, then describe the remaining uncertainty.","detailed_response":"","why_it_works":"Explain why each factor could distort the relationship and what the design can reasonably measure, balance or acknowledge."},"experimentalUnit":{"stage":10,"label":"Experimental or observational unit","type":"textarea","expected_shape":"1–3 sentences identifying assignment and measurement levels","typical_length":"about 25–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Ninety seeds are ninety independent trials.","good_working_response":"In this illustrative design, salt conditions are assigned independently to 18 dishes, making the dish the experimental unit. Five seeds in each dish are subsamples sharing that condition. The treatment comparison therefore has six independently assigned dish units per salinity group.","detailed_response":"For the illustrative 18-dish study, randomly assign six dishes to each of the three NaCl levels. Because each entire dish receives one assigned solution, the dish is the experimental unit. The five seeds within a dish provide nested measurements rather than five independent treatment replicates. There are 18 assigned experimental units in total, six per treatment group, and 90 seed observations if all planned seeds are measured. The primary analysis would use one prespecified outcome per dish, while retaining the original seed-level records. This design description does not establish that six dishes per group provide adequate statistical power.","why_it_works":"Name the independently treated unit and separate it from nested observations. In observational designs, describe the observed unit and any repeated measurements instead."},"population":{"stage":11,"label":"Target population or system","type":"textarea","expected_shape":"a clearly bounded target population or system","typical_length":"about 10–60 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Students.","good_working_response":"For a proposed classroom study, the target population is students enrolled in the school's secondary biology courses. A single available class would not automatically represent all students in those courses.","detailed_response":"","why_it_works":"Define the population of interest and distinguish it from the students or specimens who may actually be included."},"sample":{"stage":11,"label":"Actual sample","type":"textarea","expected_shape":"actual included units when known, or explicitly planned units","typical_length":"about 15–80 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Everyone in my class.","good_working_response":"For a hypothetical proposal, up to 30 students in one Grade 11 biology class might be eligible to participate, subject to approvals and voluntary consent. The final report would state how many actually enrolled and contributed analysable data.","detailed_response":"","why_it_works":"Differentiate an eligible or planned sample from a completed sample. Do not present a hypothetical recruitment count as an observed result."},"samplingMethod":{"stage":11,"label":"Sampling method and why it is feasible","type":"textarea","expected_shape":"2–4 sentences describing selection and feasibility","typical_length":"about 35–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The sample is random because everyone can sign up.","good_working_response":"An accessible biology class would provide the convenience sampling frame. Students would join only through an approved, voluntary recruitment process, so the analysed group could also reflect self-selection. Access to the class would not make the sample randomly selected from the wider student population.","detailed_response":"The proposed sampling frame is one biology class chosen because it is accessible to the researcher, making this a convenience-based recruitment approach. Participation would depend on informed and voluntary consent under the procedures approved for the setting, and students could decline without consequences for grades. The participating group may differ from other students in the class because they chose to join. Neither class availability nor voluntary sign-up constitutes a probability sample of secondary students, so findings beyond the participating class would need qualification.","why_it_works":"Describe how the class becomes accessible and how individual participants enter the study, while safeguarding genuinely voluntary participation."},"sampleLimits":{"stage":11,"label":"How sampling limits generalization","type":"textarea","expected_shape":"1–3 sentences connecting sampling to interpretation","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I have enough students to generalize.","good_working_response":"Students who volunteer from one available class may differ from those who decline and from students in other schools or curricula. The results could describe the participating group, but they would not justify estimating an association for all secondary students without stronger sampling evidence.","detailed_response":"","why_it_works":"Explain whom the sample may fail to represent and why that limits broader inference."},"instrument":{"stage":11,"label":"Instrument, measure, sensor, rubric, survey, interview, or observation procedure","type":"textarea","expected_shape":"a precise instrument or procedure with relevant specifications","typical_length":"about 20–105 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"A tool that measures things.","good_working_response":"For the seedling study, use a millimetre-marked ruler and a prespecified shoot-length measurement rule. A digital balance that displays 0.01 g increments could be used for a separate mass measure, but that display resolution alone does not establish accuracy.","detailed_response":"","why_it_works":"Name the source of the recorded value and relevant specifications without confusing instrument display resolution with measurement validity."},"measureQuality":{"stage":11,"label":"Evidence or plan for reliability, validity, calibration, or scoring consistency","type":"textarea","expected_shape":"2–4 sentences explaining checks appropriate to the construct","typical_length":"about 35–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The balance is valid because it shows two decimals.","good_working_response":"Check a balance's readings against a suitable reference mass, then zero or tare it before weighing each sample. Use the same weighing procedure and document any drift. Separately justify why mass answers the research question, since consistent readings alone do not establish construct validity.","detailed_response":"","why_it_works":"Distinguish reference checks, zeroing and procedural consistency from the question of whether the instrument measures the intended construct."},"ethicsIssues":{"stage":11,"label":"Ethical, privacy, safety, or environmental issues","type":"textarea","expected_shape":"2–4 sentences identifying concrete risks","typical_length":"about 30–115 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"There are no problems because it is schoolwork.","good_working_response":"Existing quiz grades can identify students and may be protected educational records. If the teacher recruits their own class, students may feel obliged to participate because of the grading relationship. A recruitment and data-access plan must therefore address privacy and undue influence.","detailed_response":"","why_it_works":"Describe how the proposed methods could affect participants, including people who might decline or withdraw."},"ethicsPlan":{"stage":11,"label":"How those issues will be handled and who must approve","type":"textarea","expected_shape":"2–5 sentences specifying safeguards and approval responsibilities","typical_length":"about 40–140 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Get the teacher's permission and everything is approved.","good_working_response":"Seek the school's required permissions and any applicable research ethics review before recruitment or accessing records. Use an approved process that separates consent decisions from grading, with participation and withdrawal genuinely voluntary. Minimise identifiers, restrict access to coded records and disclose clearly who can re-identify them.","detailed_response":"","why_it_works":"Specify who must review the plan and how confidentiality, consent and grading independence will be protected. Do not claim a teacher's permission substitutes for every applicable approval."},"materials":{"stage":12,"label":"Materials, software, instruments, or data sources","type":"textarea","expected_shape":"5–12 specific materials or resources, with quantities when useful","typical_length":"about 25–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Some seeds, water and equipment.","good_working_response":"An illustrative 18-dish study would need 18 labelled Petri dishes; 90 radish seeds from one batch; uniform substrate; 0, 50 and 100 mM NaCl solutions; a dispenser for equal solution volumes; a millimetre-marked ruler; and a spreadsheet with dish and seed IDs.","detailed_response":"","why_it_works":"List the items needed for this proposed protocol, including quantities that affect its interpretation. Example numbers are planning assumptions, not a sample-size justification."},"procedure":{"stage":12,"label":"Step-by-step procedure","type":"textarea","expected_shape":"one clear chronological or numbered procedure","typical_length":"120–250 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Give the seeds salt, then check whether they grow.","good_working_response":"In an illustrative sequence, label and assign 18 dishes; plant five seeds per dish; apply the assigned solution volume; standardise growing conditions; record each seed's Day 7 shoot length; and calculate one mean per dish.","detailed_response":"This is an illustrative protocol to adapt before collecting data. Label 18 Petri dishes with neutral identifiers and use a documented random allocation to assign six dishes to each of three solution concentrations, 0, 50 or 100 mM NaCl. Record the allocation key separately from the measurement sheet. Place five radish seeds from the same batch on a consistent substrate in each dish and assign unique seed IDs within each dish. Prepare the solutions with appropriate supervision, and dispense an equal, prespecified volume into each dish. Record the actual volume and maintain a consistent light schedule, temperature range and observation period. Randomise or periodically rearrange dish positions according to a plan that does not depend on observed growth. On Day 7, record germination status and measure shoot length from the substrate surface to the shoot tip in centimetres. For the prespecified primary outcome, enter 0 cm for a seed with no shoot and calculate one mean shoot length per planted seed for each dish. Retain seed-level measurements linked to their dish IDs. Document missing observations and departures from the procedure when they occur. Review whether the proposed number of dishes is sufficient before beginning the study.","why_it_works":"Show how treatment assignment, nested measurements, recording rules and departures from the procedure will be managed. Settle remaining implementation details before data collection."},"replication":{"stage":12,"label":"Number of units, trials, repeated measurements, or observations and why","type":"textarea","expected_shape":"2–4 sentences separating treatment units from nested observations","typical_length":"about 30–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"There are 90 independent replicates because there are 90 seeds.","good_working_response":"In the illustrative study, 18 independently assigned dishes provide six experimental units per salinity level. Each dish contains five seeds, giving 90 seed observations if all are recorded. The seeds are nested within dishes, so they are not 90 independent treatment replicates. Sample-size adequacy still requires justification.","detailed_response":"","why_it_works":"Count independent treatment units separately from repeated or nested observations. Explain how the proposed number of units was chosen without claiming that replication automatically establishes power."},"methodControls":{"stage":12,"label":"Randomization, counterbalancing, blinding, standardization, control condition, or other validity protections","type":"textarea","expected_shape":"2–4 sentences describing actual or planned protections","typical_length":"about 30–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Randomisation and blinding will solve every problem.","good_working_response":"Assign dishes to salinity levels using a recorded random sequence, then distribute their shelf positions using a prespecified plan. Keep seed batch, solution volume, light and measurement timing as consistent as feasible. If the scorer can be blinded to the concentration codes, record how this will be done.","detailed_response":"","why_it_works":"Explain how each feasible protection is implemented and which bias it addresses. A random process must be real and documented."},"rowUnit":{"stage":12,"label":"What one row represents","type":"text","expected_shape":"a short phrase or one sentence","typical_length":"about 3–25 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"One row is a result.","good_working_response":"One row represents one planted seed measured on Day 7; dish_id identifies the independently treated dish.","detailed_response":"","why_it_works":"Define the observation represented by the row and preserve the identifier linking each seed to its treatment unit."},"columns":{"stage":12,"label":"Planned columns, variable names, units/categories","type":"textarea","expected_shape":"5–10 column definitions with units or coding","typical_length":"about 20–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"ID, treatment, results and other details.","good_working_response":"dish_id (dish identifier); seed_id (seed identifier within dish); NaCl_mM (0, 50 or 100 mmol/L); day (days after setup); germinated (0 = no, 1 = yes); shoot_length_cm (centimetres); missing_reason (coded category, if relevant).","detailed_response":"","why_it_works":"Provide enough metadata to interpret each column and keep the seed observations linked to their dish. Use concentration units consistent with the assigned treatments."},"missingRule":{"stage":12,"label":"Missing-data rule","type":"textarea","expected_shape":"2–4 sentences distinguishing genuine missingness and valid zeroes","typical_length":"about 30–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I will write zero whenever a number is missing.","good_working_response":"Record a genuinely unobserved shoot length as missing and add the reason when known. Under the prespecified outcome definition, a seed without a shoot is measured as 0 cm and is not missing. Review incomplete dishes separately and decide their handling before analysing group differences.","detailed_response":"","why_it_works":"Define the difference between a meaningful zero and an absent measurement, then preserve the reason and analysis implications of missingness."},"exclusionRule":{"stage":12,"label":"Exclusion/outlier rule decided in advance","type":"textarea","expected_shape":"2–4 sentences defining and documenting exclusions","typical_length":"about 30–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Remove the unusual values so the results look cleaner.","good_working_response":"Correct a transcription error only when the original measurement record establishes the intended value, keeping both the original and corrected entry. Flag measurements without a reliable dish or seed identifier and document any exclusion rule before analysing outcomes. Retain extreme values that are biologically plausible.","detailed_response":"","why_it_works":"Use reproducible evidence-based criteria and retain an audit trail. An unexpected numerical value alone is not a reason for exclusion."},"analysisIntent":{"stage":12,"label":"Primary descriptive and inferential/qualitative analysis plan","type":"textarea","expected_shape":"2–4 sentences specifying the primary comparison and unit","typical_length":"about 30–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I will calculate a p-value for plant growth.","good_working_response":"The primary comparison will estimate the difference in mean Day 7 shoot length per planted seed between dishes assigned to 0 and 100 mM NaCl. Each dish contributes one mean, preserving independent treatment units. The 50 mM condition will be described separately unless further comparisons are prespecified.","detailed_response":"","why_it_works":"Identify the target quantity and the relevant units before choosing an analysis, and distinguish the primary comparison from additional work."},"rawLocation":{"stage":13,"label":"Where the unchanged raw data are stored","type":"textarea","expected_shape":"a named protected location and method for preserving originals","typical_length":"about 25–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Everything is on my computer somewhere.","good_working_response":"Illustrative storage plan. Keep the original export as raw_data_original.csv in a school-approved folder with access restricted to authorised researchers. Store cleaning decisions and any corrected copies separately, and record the actual folder location in the project documentation.","detailed_response":"","why_it_works":"Specify where the unchanged evidence will be preserved and who is authorised to access it. Do not use an invented file path as proof of storage."},"missingObserved":{"stage":13,"label":"Missing observations and how they were handled","type":"textarea","expected_shape":"1–3 sentences reporting verified missingness","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"A few values were missing, so I ignored them.","good_working_response":"Hypothetical report only. If 2 of 30 students lacked follow-up records, a complete-pair analysis would include at most 28 students. The report would state the actual missing-data reasons, whether other exclusions occurred and how the missingness may affect interpretation.","detailed_response":"","why_it_works":"Use verified counts and describe the resulting analysis sample. Missing observations may be systematic rather than harmless."},"errorsCorrections":{"stage":13,"label":"Data-entry errors, corrections, exclusions, or protocol deviations","type":"textarea","expected_shape":"1–3 sentences identifying the evidence for each correction","typical_length":"about 20–100 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I fixed the data after checking it.","good_working_response":"Illustrative correction log. If a spreadsheet showed 55.0 cm in row 14 but the original measurement sheet recorded 5.5 cm, retain both values and document the reason for the correction. Without the original source, the difference alone would not justify changing it.","detailed_response":"","why_it_works":"Preserve the original entry, the corrected entry and the independent evidence that warrants the correction."},"plots":{"stage":13,"label":"Plots/figures used to inspect the data","type":"textarea","expected_shape":"1–4 figures with the specific pattern each displays","typical_length":"about 20–95 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Make a graph of the experiment.","good_working_response":"A dot plot of the six dish-level mean shoot lengths per salinity condition would show the variation among independently assigned dishes. A separate display of dish-level germination proportions could show whether germination contributes to differences in the combined outcome.","detailed_response":"","why_it_works":"Choose figures that reveal the actual distribution or comparison and make the independent and nested units clear."},"descriptives":{"stage":13,"label":"Descriptive statistics or qualitative corpus summary","type":"textarea","expected_shape":"2–5 appropriate numerical or qualitative summaries","typical_length":"about 25–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Calculate the average of everything.","good_working_response":"For each salinity condition, report the number of analysed dishes, mean dish-level shoot length and a suitable measure of variation such as SD or range. Summarise germination with appropriate counts or proportions, and record how many dishes have incomplete data.","detailed_response":"","why_it_works":"Choose summaries that correspond to the outcome and unit. Qualitative projects should instead describe their corpus and relevant evidence characteristics."},"primaryEstimand":{"stage":14,"label":"The quantity that most directly answers my question","type":"textarea","expected_shape":"a specified quantitative target with comparison, unit and population or setting","typical_length":"about 15–75 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The difference between the groups.","good_working_response":"For the illustrative experiment, the primary quantity is the population mean difference in dish-level Day 7 shoot length per planted seed between the 0 mM and 100 mM NaCl conditions. The 50 mM condition would be secondary to this prespecified contrast.","detailed_response":"","why_it_works":"Define the quantitative estimand before selecting a test. In mixed-methods work, explain separately what the qualitative strand is intended to understand."},"analysisChoice":{"stage":14,"label":"Primary analysis and justification","type":"textarea","expected_shape":"2–5 sentences tying the method to units and assumptions","typical_length":"about 35–140 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I will use whichever statistical test produces significance.","good_working_response":"A comparison of dish-level means between the prespecified 0 and 100 mM groups could use a Welch two-sample t-test if its assumptions and the sample size are judged adequate. The dishes are independently assigned, while seeds within a dish are nested observations. Report the raw mean difference and uncertainty alongside any test result.","detailed_response":"The primary contrast is the difference in mean Day 7 shoot length per planted seed between the 0 mM and 100 mM NaCl conditions. Each dish will contribute one prespecified mean, so the comparison concerns six independently assigned dishes in each group rather than the 30 seeds observed within each. A Welch two-sample t-test is one possible inferential method if the design and the observed distribution of dish outcomes support its assumptions. With only six dishes per group, the method's suitability and likely uncertainty require particular care. Report group distributions, the raw difference in centimetres and a confidence interval when defensible. The 50 mM group remains secondary unless additional comparisons were defined before analysis.","why_it_works":"Match the analysis to the experimental units, the outcome and the target comparison. A named test does not by itself establish adequate sample size or assumptions."},"assumptionChecks":{"stage":14,"label":"Assumptions/design checks and what I observed","type":"textarea","expected_shape":"2–5 sentences describing planned or completed diagnostic checks","typical_length":"about 35–135 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The data were normal.","good_working_response":"Check that dishes were independently assigned and measured, then inspect dish-level outcomes in each comparison group for extreme values or pronounced asymmetry. Six dishes per group provide little information about distributional shape, so normality should not be declared from a routine test alone. Record the actual observations after analysis.","detailed_response":"","why_it_works":"Distinguish properties established by the design from patterns that require the observed data, and document limitations of diagnostic checks."},"effectSizePlan":{"stage":14,"label":"Effect size and/or interval estimate","type":"textarea","expected_shape":"1–3 sentences specifying magnitude and uncertainty","typical_length":"about 25–105 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I will report whether p is below .05.","good_working_response":"Report the raw difference between mean dish-level Day 7 shoot lengths in the 0 and 100 mM groups, in centimetres. Include an appropriate confidence interval if the analysis assumptions support it. A standardised effect estimate is optional and needs its own justification.","detailed_response":"","why_it_works":"Choose a magnitude in an interpretable unit and explain how uncertainty will be communicated, beyond any significance test."},"multiplicity":{"stage":14,"label":"Multiple comparisons or exploratory analyses and how I will handle/label them","type":"textarea","expected_shape":"2–4 sentences distinguishing primary and additional comparisons","typical_length":"about 30–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Try every comparison and report only significant ones.","good_working_response":"Prespecify the 0 versus 100 mM dish-level contrast as the primary analysis. Describe the 50 mM group without treating it as another confirmatory result unless additional comparisons are planned and multiplicity is addressed. Label any analyses decided after seeing the data as exploratory.","detailed_response":"","why_it_works":"Make planned and exploratory comparisons distinguishable. Document all tests and use an appropriate multiplicity approach where several confirmatory comparisons are performed."},"analysisSample":{"stage":15,"label":"Final analyzed sample/corpus and exclusions","type":"textarea","expected_shape":"2–4 sentences identifying actual analysed units and exclusions","typical_length":"about 25–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I analysed all the data that seemed useful.","good_working_response":"Illustrative reporting structure. Of the 18 dishes planned, [actual count] contributed complete Day 7 data, including [counts] in the three salinity conditions. Explain any excluded dish or missing seed measurements, and report the final number of independently treated units rather than presenting seed rows as independent samples.","detailed_response":"","why_it_works":"Record the observed analysis sample and every change from planned recruitment or assignment. Replace bracketed quantities with verified counts."},"result1":{"stage":15,"label":"Primary result and exact supporting output/table/figure","type":"textarea","expected_shape":"2–4 sentences reporting a source-traceable finding","typical_length":"about 30–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The salt treatment worked and the result was significant.","good_working_response":"Illustrative reporting template, with no results asserted. Mean Day 7 shoot length per planted seed differed by [estimate] cm between the 0 and 100 mM dish groups, with a 95% confidence interval of [lower, upper] cm if justified by the analysis. Refer to the verified output and Table [number].","detailed_response":"","why_it_works":"Report the actual estimate and appropriate uncertainty, then point to the record that supports them. A bracketed model is not a substitute for completed analysis."},"result2":{"stage":15,"label":"Secondary result and exact supporting output/table/figure","type":"textarea","expected_shape":"1–3 sentences reporting a documented secondary outcome","typical_length":"about 25–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The other result was even more interesting.","good_working_response":"If germination was a prespecified secondary outcome, report the observed proportion in each independently assigned dish group with the source table. State whether the secondary comparison was planned or exploratory, and avoid describing a direction of difference before seeing the actual evidence.","detailed_response":"","why_it_works":"Report secondary findings with the same traceability and care as primary findings, while keeping their inferential status clear."},"unexpected":{"stage":15,"label":"Null, weak, unexpected, or contradictory result","type":"textarea","expected_shape":"1–3 sentences reporting a null or uncertain finding","typical_length":"about 25–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"There was no effect because p was not significant.","good_working_response":"Illustrative reporting structure. If the estimated difference is imprecise, give the estimate and confidence interval, then explain that the data remain compatible with multiple plausible effects. Do not turn an inconclusive test into proof that the conditions are equivalent.","detailed_response":"","why_it_works":"Preserve the magnitude and uncertainty of a weak, unexpected or null result instead of reducing it to significance."},"resultsDraft":{"stage":15,"label":"Results section draft","type":"textarea","expected_shape":"1–3 connected Results paragraphs, with traceable evidence","typical_length":"120–300 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The higher salt group had worse growth, so salt harmed the plants.","good_working_response":"Illustrative Results opening. The analysis retained [number] independently assigned dishes. Their Day 7 outcomes were summarised at the dish level, and the prespecified 0 versus 100 mM contrast is reported with its observed mean difference, uncertainty and source table. Replace every placeholder using actual output.","detailed_response":"Illustrative Results template. The bracketed information below is deliberately unfilled and must be replaced with documented analysis outputs. The planned experiment used independently assigned dishes, with five seeds measured within each dish. After exclusions and missing observations were reviewed, [number] dishes contributed to the primary analysis, including [number] assigned to 0 mM and [number] assigned to 100 mM NaCl. The remaining dishes were assigned to 50 mM. Dish-level outcomes were calculated from the retained seed-level records using the prespecified Day 7 measurement rule.\n\nMean shoot length per planted seed was [estimate] cm in the 0 mM group and [estimate] cm in the 100 mM group, with [appropriate measures of variability]. Individual dish values and distributions are shown in Figure [number]. The prespecified contrast between these two conditions gave a mean difference of [estimate] cm with a 95% confidence interval of [lower, upper] cm, calculated using [verified analysis method]. If no inferential analysis was appropriate, this sentence would instead describe the observed difference and its limitations.\n\nThe 50 mM group had [descriptive summary], reported separately from the primary comparison. Germination status was summarised as [appropriate counts or proportions] in Table [number]. Any missing measurements, deviations or supplementary analyses are documented in [record]. These statements describe the required reporting structure; they do not represent collected results.","why_it_works":"Develop the Results around the research question and the evidence, using connected paragraphs and exact traceable outputs. Bracketed model values must be replaced before submission."},"directAnswer":{"stage":16,"label":"Direct answer to the research question","type":"textarea","expected_shape":"1–2 sentences answering within the design's limits","typical_length":"about 20–90 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Yes, the study proved the treatment causes the outcome.","good_working_response":"An illustrative answer depends on the observed dish-level comparison. If mean Day 7 shoot length differs across the assigned salinity conditions, report its direction and estimated magnitude with uncertainty. Generalisation beyond the studied seed batch and conditions remains limited.","detailed_response":"","why_it_works":"Answer the research question using the actual results and preserve the distinction between an experimental contrast and broader population claims."},"interpret1":{"stage":16,"label":"Interpretation of anchor finding 1 with evidence boundary","type":"textarea","expected_shape":"2–4 sentences linking findings with qualified explanation","typical_length":"about 35–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Salt definitely caused osmotic stress inside every seed.","good_working_response":"If the higher-salinity dishes have lower mean Day 7 shoot length, reduced water availability or ionic stress may offer possible biological explanations. Neither mechanism was directly measured by the shoot-length outcome. The interpretation should therefore remain a hypothesis informed by appropriate literature rather than a demonstrated mechanism.","detailed_response":"","why_it_works":"Relate the observed pattern to plausible explanations while distinguishing measured outcomes from unmeasured mechanisms."},"interpret2":{"stage":16,"label":"Interpretation of anchor finding 2 with evidence boundary","type":"textarea","expected_shape":"2–4 sentences identifying a secondary finding's contribution","typical_length":"about 35–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The germination data confirmed everything.","good_working_response":"If germination is similar across conditions while mean shoot length differs, the measurements may suggest that growth after emergence contributed more clearly to the observed pattern. The combined outcome includes ungerminated seeds, so a comparison among germinated seedlings would require separate analysis and careful interpretation.","detailed_response":"","why_it_works":"Use the second finding to qualify the first, with attention to how outcome definitions affect the interpretation."},"litCompare":{"stage":16,"label":"How findings converge with or differ from prior literature","type":"textarea","expected_shape":"2–4 sentences comparing documented studies with one's findings","typical_length":"about 35–130 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"My findings agree with all the research.","good_working_response":"An illustrative comparison might find a similar direction of shoot-length differences in two published seedling studies, although their salinity ranges and outcomes may differ. Verify the studies, report their actual estimates and cite them before claiming convergence. A shared direction does not automatically establish comparable effect magnitude.","detailed_response":"","why_it_works":"Compare identified findings and methods in sources you have read, making agreements, differences and limits of comparability specific."},"alternatives":{"stage":16,"label":"Alternative explanations or mechanisms","type":"textarea","expected_shape":"2–4 sentences explaining credible alternative pathways","typical_length":"about 35–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Lots of other things might have happened.","good_working_response":"In a hypothetical seedling comparison, differences in water availability, ionic conditions or growth after germination might contribute to observed shoot-length patterns. Uneven moisture or dish position could also matter if procedures varied across conditions. The measurements would need to distinguish these possibilities before any specific mechanism could be claimed.","detailed_response":"","why_it_works":"Identify alternatives that the design makes plausible and clarify what additional evidence would help distinguish them."},"limitations":{"stage":16,"label":"At least two limitations and exactly how each restricts claims","type":"textarea","expected_shape":"at least two concrete limitations and their consequences","typical_length":"about 45–145 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The study had some problems.","good_working_response":"Six independently assigned dishes per treatment could leave substantial uncertainty in the estimated mean difference, especially if dish outcomes vary widely. The single seed batch and growing setting would limit generalisation to other conditions. Because the primary outcome averages shoot length across planted seeds, including zeroes for seeds without shoots, it would not separate germination differences from growth among germinated seedlings.","detailed_response":"In this illustrative design, the primary comparison would use only six independently assigned dishes per treatment. The resulting estimate could be imprecise, and the five seeds within a dish would not constitute additional independent treatment replicates. A single seed batch in one growing setting would also limit how confidently the results could be applied to other plant populations or environments. The prespecified Day 7 outcome includes zero values for seeds without visible shoots, so the dish-level mean reflects a combination of germination and subsequent growth. A difference in this measure could not, on its own, establish which developmental process was responsible. Actual protocol deviations and missing observations would need to be checked before describing further limitations.","why_it_works":"State how a particular feature of the design, sample or measurement restricts the interpretation, rather than merely listing weaknesses."},"implications":{"stage":16,"label":"Realistic implications and who/what they apply to","type":"textarea","expected_shape":"2–4 sentences about justified, bounded uses of the findings","typical_length":"about 35–115 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The experiment proves what all plants need.","good_working_response":"If the planned experiment identifies a reliable difference between the salinity conditions, it could inform a limited classroom discussion of how early development responds in this particular system. The result would need confirmation with more independently assigned units and other seed batches before supporting broader horticultural recommendations.","detailed_response":"","why_it_works":"Explain who could use the evidence and where stronger replication or more direct measurement would be needed."},"future":{"stage":16,"label":"Specific future research that follows from the findings","type":"textarea","expected_shape":"1–2 specific sentences linked to observed limitations","typical_length":"about 20–80 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Scientists should study this more.","good_working_response":"A subsequent experiment could include more independently assigned dishes, use several radish seed batches and measure germination separately from shoot length among emerged seedlings. Planning an adequate number of treatment units in advance would strengthen the comparison.","detailed_response":"","why_it_works":"Connect a feasible next design directly to a documented uncertainty or measurement limitation."},"discussionDraft":{"stage":16,"label":"Discussion draft","type":"textarea","expected_shape":"3–6 connected paragraphs that develop evidence-bound interpretations","typical_length":"300–700 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The findings proved that salt harms plants, just as other studies did.","good_working_response":"Illustrative Discussion opening only. If the completed dish-level analysis shows a difference in mean Day 7 shoot length between 0 and 100 mM NaCl, interpret its direction and uncertainty in the context of the actual design. Discuss which biological mechanisms remain unmeasured and compare only verifiable literature findings.","detailed_response":"Illustrative Discussion for a hypothetical study. The assumed patterns below are fictional and must be replaced by findings from an actual analysis.\n\nSuppose dishes assigned the highest NaCl concentration had shorter mean shoot length per planted seed than those receiving the reference solution. The primary comparison would then describe a difference in early development under the conditions studied. Its estimated magnitude and uncertainty would need to be reported from the dish-level analysis before deciding how firmly the pattern could be interpreted. The observations would concern the experimental dishes and seed batch used in the study. A broader claim about radish plants in other settings would require further evidence.\n\nSeveral biological processes might contribute to such a difference. Added salt could change water availability or create ionic stress, although shoot length alone would not identify either mechanism. The chosen outcome also combines germination and subsequent shoot growth by assigning 0 cm to seeds without visible shoots on Day 7. A lower dish-level mean might therefore arise from fewer seeds developing shoots, shorter shoots among those that emerged, or both. Germination records could help explore these possibilities. Any additional comparison among germinated seedlings would need to be clearly described, since selecting only those that germinated changes the group being compared.\n\nA useful literature comparison would examine studies that report comparable species, concentration ranges and measurement times. The manuscript must identify those studies and cite their actual findings before claiming agreement or disagreement. Even when two investigations show a similar direction of difference, their reported magnitudes may be difficult to compare if one measures germination percentages and another measures length among surviving seedlings. Such differences in outcome definition shape the interpretation of apparent convergence.\n\nThe proposed design contains six independently assigned dishes per concentration. Measurements from five seeds within one dish increase detail about that dish, while the number of independent treatment units remains six per group. This modest replication could produce imprecise estimates, and a single seed batch or classroom growing environment further limits generalisation. Position-related differences in light or moisture would warrant attention if the planned controls were not maintained consistently. These limitations should be discussed using the recorded deviations and observed distributions, without assuming that every possible source of error occurred.\n\nA subsequent study could use more independently assigned dishes selected through a justified sample-size plan, repeat the work across seed batches, and distinguish germination from growth among seedlings. That extension would help examine which aspects of early development respond under particular salinity conditions. For the present illustration, the central obligation is narrower. The Discussion should explain what the measurements actually support and leave unresolved mechanisms open to further investigation.","why_it_works":"Develop interpretation through the actual measured pattern, relevant explanations, literature, concrete limitations and a defensible next question. The paragraphs are connected by the argument, not by a compulsory list of rhetorical moves."},"conclusionDraft":{"stage":17,"label":"Conclusion","type":"textarea","expected_shape":"2–4 sentences closing on findings or a proposed study purpose","typical_length":"about 30–110 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The hypothesis was correct, and this proves salt stops growth.","good_working_response":"For a completed experiment, the conclusion should report the observed direction and magnitude of the dish-level salinity comparison only after analysis. Any conclusion about early development would remain bounded by the seed batch, treatment units and combined growth measure. A proposal should instead close on its planned question and anticipated evidence without claiming results.","detailed_response":"","why_it_works":"Close with the actual answer when one exists, or the study purpose when work remains proposed. Keep limitations proportionate and introduce no new findings."},"abstractDraft":{"stage":17,"label":"Abstract","type":"textarea","expected_shape":"one coherent paragraph appropriate to proposal or completed work","typical_length":"150–250 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"We tested salt, and the findings were very significant.","good_working_response":"Illustrative proposal abstract. The proposed experiment would compare mean shoot length per planted seed at Day 7 under assigned 0, 50 and 100 mM NaCl conditions. Eighteen dishes are envisioned, with treatment assigned at the dish level and five seeds observed per dish. Any conclusions would depend on the subsequent evidence and the adequacy of replication.","detailed_response":"This proposed classroom laboratory study would examine early radish development under three assigned sodium chloride concentrations. The research question concerns mean shoot length per planted seed after seven days, with particular attention to the comparison between dishes receiving 0 mM and 100 mM NaCl. In the illustrative design, 18 dishes would be independently assigned across 0, 50 and 100 mM conditions, with six dishes per concentration and five seeds within each dish. Each dish would contribute one mean outcome to the primary comparison, while individual seed records and germination status would be retained to clarify the measurement. Seeds without visible shoot growth at the designated time would be assigned 0 cm under a prespecified outcome definition that combines germination and subsequent growth. Random allocation and consistent growing procedures would be documented, and the adequacy of the proposed number of dishes would require review before collection. The study could describe differences under the specified laboratory conditions, with interpretation limited by its experimental replication, seed batch and measurement choices. No empirical findings are reported here because the study is presented as a proposal rather than a completed investigation.","why_it_works":"Summarise the purpose, system, design and planned analysis in a proposal, without reporting results that do not exist. A completed-study abstract must instead include verified central findings."},"titleDraft":{"stage":17,"label":"Proposed title","type":"text","expected_shape":"a short phrase or one sentence","typical_length":"about 3–25 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"The Impact of Salt on All Plants","good_working_response":"Early Radish Shoot Growth Across Assigned Salinity Conditions","detailed_response":"","why_it_works":"Use a specific title that identifies the system and comparison without implying that the results or mechanism have already been established."},"keywords":{"stage":17,"label":"Keywords","type":"text","expected_shape":"3–6 searchable keywords or short phrases","typical_length":"about 3–20 words total","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"science; data; experiment","good_working_response":"salinity; radish seedlings; shoot length; experimental units; early plant growth","detailed_response":"","why_it_works":"Select terms that describe this study's actual system, outcomes or method and that would help a relevant reader locate it."},"citationStyle":{"stage":18,"label":"Required citation style","type":"select","expected_shape":"one selection","typical_length":"Choose the option that matches your project. Use the nearby explanation field to justify it when one is provided.","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Whatever referencing style is easiest.","good_working_response":"APA 7","detailed_response":"","why_it_works":"Use the exact option required by the teacher, journal or assignment. Follow the applicable official conventions rather than mixing styles."},"citationAudit":{"stage":18,"label":"Citation/reference issues I still need to fix","type":"textarea","expected_shape":"2–6 specific issues to verify against source records","typical_length":"about 20–125 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"I need to fix the references.","good_working_response":"An in-text author–date citation has no matching verified publication record; identify the source before retaining the claim. Confirm article titles, publication years and DOIs against the actual publications, and review whether every cited claim is supported by the referenced material.","detailed_response":"","why_it_works":"Record concrete, auditable problems while avoiding invented author names, DOIs or source details."},"finalEdits":{"stage":18,"label":"Final methodological or writing revisions","type":"textarea","expected_shape":"2–6 concrete actions needed for submission","typical_length":"about 25–120 words","length_note":"This is a working range, not a grading rule. Write enough to make the research decision clear and specific.","too_vague":"Read it again and make it sound professional.","good_working_response":"Reconcile the number of independently assigned dishes across Methods and Results; verify that figures display dish-level comparisons; confirm the rule distinguishing ungerminated seeds from missing measurements; check every citation against its source; and revise any claims that exceed the recorded evidence.","detailed_response":"","why_it_works":"Make each remaining action specific enough that another reader can verify whether it has been completed."}}};
